drop table MST_CREDIT_MARKET_INFO;
create table  MST_CREDIT_MARKET_INFO
(
    SECID                      varchar2(50)   not null ,
    CDATE                      varchar2(10)   not null ,
    MDPRICE                    NUMBER(18,12)  not null ,
    MCPRICE                    NUMBER(18,12)    ,
    MINT                       NUMBER(18,12)    ,
    MYIELD                     NUMBER(18,12)    ,
    M_MDURATION                NUMBER(18,12)    ,
    M_CNVXTY                   NUMBER(18,12)    ,
		ISSUE_MARKET_NUM           NUMBER(18,12)    ,
		CREDIT_TYPE                VARCHAR2(50)     ,
		VALUE_SOURCE               VARCHAR(50)      ,
		CREATE_USER                VARCHAR(20)      ,
		CREATE_DEPT                VARCHAR(20)      ,
		CREATE_TIME                TIMESTAMP       ,
		UPDATE_USER                VARCHAR(20)     ,
		UPDATE_TIME                TIMESTAMP       ,
    primary key (SECID,CDATE)
);

comment on TABLE MST_CREDIT_MARKET_INFO is '信用保护凭证行情';
comment on COLUMN MST_CREDIT_MARKET_INFO.CDATE is '估值日';
comment on COLUMN MST_CREDIT_MARKET_INFO.MDPRICE is '估值全价';
comment on COLUMN MST_CREDIT_MARKET_INFO.MCPRICE is '估值净价';
comment on COLUMN MST_CREDIT_MARKET_INFO.MINT is '应计利息';
comment on COLUMN MST_CREDIT_MARKET_INFO.MYIELD is '估价收益率（%）';
comment on COLUMN MST_CREDIT_MARKET_INFO.M_MDURATION is '估价修正久期';
comment on COLUMN MST_CREDIT_MARKET_INFO.M_CNVXTY is '市价凸性';
comment on COLUMN MST_CREDIT_MARKET_INFO.ISSUE_MARKET_NUM is '发行市场数';
comment on COLUMN MST_CREDIT_MARKET_INFO.CREDIT_TYPE is '信用类型';
comment on COLUMN MST_CREDIT_MARKET_INFO.VALUE_SOURCE is '估值来源(中债CBC、中证CSD、SCH 上清所)';
comment on COLUMN MST_CREDIT_MARKET_INFO.CREATE_USER is '创建人';
comment on COLUMN MST_CREDIT_MARKET_INFO.CREATE_DEPT is '创建部门';
comment on COLUMN MST_CREDIT_MARKET_INFO.CREATE_TIME is '创建时间';
comment on COLUMN MST_CREDIT_MARKET_INFO.UPDATE_USER is '更新人';
comment on COLUMN MST_CREDIT_MARKET_INFO.UPDATE_TIME is '更新时间';

